function setup(){paused=true;sound.pause(true);$('minase-modal').style.display='grid';$('minase-modal').innerHTML='<section class="modalbox"><div class="eyebrow">STATION 01 / MINASE</div><h2>単線を、譲り合う。</h2><p>1面2線の交換駅。基本は下り1番線・上り2番線。1番線は上下方向に発着でき、上り列車の待避や折り返しにも使います。</p><div class="difficultychoices">'+Object.entries(M.MODES).map(([k,v])=>'<button data-mode="'+k+'" class="'+(k===mode?'active':'')+'"><strong>'+v.label+'</strong><small>'+v.note+'・'+v.count+'本／5分＋単独1本</small></button>').join('')+'</div><div class="modechoices">'+[5,10,15].map(n=>'<button data-minutes="'+n+'" class="'+(n===minutes?'active':'')+'"><strong>'+n+'分</strong><small>'+M.planFor(n,mode).length+'列車</small></button>').join('')+'</div><p>開始前10秒は準備時間。時間を超えても最終列車の隣駅到着まで続きます。</p><div class="resultactions"><a class="station-select" href="index.html">駅選択</a><button id="minase-start" class="primary">この条件で勤務開始</button>'+(station.running&&!station.finished?'<button id="minase-return">今の勤務に戻る</button>':'')+'</div></section>';for(const b of document.querySelectorAll('[data-mode]'))b.onclick=()=>{mode=b.dataset.mode;setup();};for(const b of document.querySelectorAll('[data-minutes]'))b.onclick=()=>{minutes=+b.dataset.minutes;setup();};$('minase-start').onclick=()=>{sound.reset();station=new M.Station(minutes,mode).begin();selected=null;shown=false;paused=false;$('minase-modal').style.display='none';audio?.ready();paint();};if($('minase-return'))$('minase-return').onclick=()=>{paused=false;$('minase-modal').style.display='none';};}
function desired(t){if(!t)return null;return t?.loc===t.from+'I'?M.routeDef(t.from,'in',t.p):t?.loc.startsWith('P')?M.routeDef(t.to,'out',+t.loc.slice(1)):null;}
function state(t){if(t.gone)return'取扱完了';if(t.loc.endsWith('Q'))return'隣駅で閉塞待ち';if(t.loc.endsWith('I'))return'接近・場内信号待ち';if(t.loc.startsWith('P'))return t.reverseUntil>station.time?'運転台交換 あと'+Math.ceil(t.reverseUntil-station.time)+'秒':t.hold&&station.records[t.hold]?.dep===null?t.hold+' 特急先発待ち':t.doors==='closing'?'ドア閉め中':t.doors==='checking'?'閉扉確認中':'停車・出発待ち';return'進出中';}
function actual(n,due){return n===null?'未':time(n)+(n-due>.5?'（+'+Math.round(n-due)+'秒）':'');}
let panelRenderQueued=false;function paint(){if(panelRenderQueued)return;panelRenderQueued=true;requestAnimationFrame(()=>{panelRenderQueued=false;paintNow();});}
function paintNow(){const s=station,r=s.result();for(const side of ['W','E']){const a=sound.approaches[side],active=!!a.id&&!a.ack&&!sound.paused&&!sound.muted&&sound.volume>0;const state=$('minase-audio-state-'+side);state.textContent=!a.id?'待機':a.ack?'確認済み':sound.muted?'消音中':sound.paused?'一時停止':'動作中';state.classList.toggle('ringing',active);$('minase-stop-'+side).disabled=!a.id||a.ack;$('minase-panel-audio-'+side).setAttribute('class','cabinet-indicator'+(active?' on':''));$('minase-panel-state-'+side).textContent=active?'動作中':'停止中';}for(const[loc,id]of [['W','number-W'],['P1','number-1'],['P2','number-2'],['E','number-E']]){const t=loc[0]==='P'?s.trainAt(loc):s.trains.find(t=>!t.gone&&t.loc.startsWith(loc));$(id).textContent=t?.id||'—';}$('minase-clock').textContent=time(s.time);$('minase-shift').textContent=s.finished?'勤務終了':!s.running?'勤務前':paused?'一時停止':s.time<0?'準備中 あと'+Math.ceil(-s.time)+'秒':s.time>=s.duration?'延長運転 · 残り'+s.trains.filter(t=>!t.gone).length+'列車':M.MODES[s.difficulty].label+' · 残り'+Math.ceil((s.duration-s.time)/60)+'分';$('minase-pause').textContent=paused?'再開':'一時停止';$('minase-pause').disabled=!s.running||s.finished;$('minase-events').textContent=r.completed+' / '+r.total;$('minase-delay').textContent=Math.round(r.delay)+'秒';$('minase-notice').textContent=s.note;
 const displayBlock=(id,route)=>id==='WO'?'WI':id==='EO'?'EI':id.endsWith('T')?id[0]+(route?.split('-')[2]||'1'):id;const occupied=new Set(s.trains.flatMap(t=>s.occupied(t).map(id=>displayBlock(id,id===t.loc?t.route:t.tailRoute)))),reserved=new Set(s.routes.flatMap(r=>r.paths.map(id=>displayBlock(id,r.id))));for(const[id,lamp]of Object.entries(lamps))lamp.setAttribute('class','circuit-window '+(occupied.has(id)?'occupied':reserved.has(id)?'reserved':''));for(const[id,v]of Object.entries(rotors)){const on=v.point?s.points[id].value:id==='E-in'?Object.entries(s.handles).some(([key,held])=>held&&key.startsWith('E-in-')):s.handles[id];v.b.classList.toggle('reverse',!!on);v.b.classList.toggle('moving',v.point&&!!s.points[id].moving);v.b.disabled=v.point&&(!s.running||s.finished||!!s.pointLocks(id).length||!!s.points[id].moving);v.b.setAttribute('aria-pressed',String(!!on));v.state.textContent=(on?'R':'N')+(v.point?(+id>=31?(on?' 本線':' 安全側線'):(on?' 2番線':' 1番線')):(id==='E-in'&&on?' '+(s.arrivalRoute('E')?.p||(s.points['21'].value?2:1))+'番線へ':on?' 反位':' 停止'));if(!v.point){const a=s.signalAspect(id),lamp=signals[id];lamp.setAttribute('fill',a.color);lamp.setAttribute('aria-label',lamp.dataset.caption+'：'+a.label+' '+a.speed+'km/h');}}
 const trains=$('minase-trains');const liveIds=new Set(s.trains.filter(t=>!t.gone).map(t=>t.id));for(const[id,v]of Object.entries(trainViews))if(!liveIds.has(id)){v.g.remove();delete trainViews[id];}for(const t of s.trains.filter(t=>!t.gone)){const id=displayBlock(t.loc,t.route),rail=rails[id];if(!rail)continue;let v=trainViews[t.id];if(!v){const g=svg('g',{},trains);svg('rect',{x:-27,y:-31,width:54,height:18,fill:'#08252d',stroke:'#a9c9c7'},g);const n=svg('text',{x:-20,y:-18,class:'terminal-train-id'},g);n.textContent=t.id;v=trainViews[t.id]={g,loc:null};}if(v.loc!==id){const pt=rail.getPointAtLength(rail.getTotalLength()/2);v.g.setAttribute('transform','translate('+pt.x+' '+(pt.y-(['WI','WT','EI','ET'].includes(t.loc)?32:0))+')');v.loc=id;}}
 const live=s.trains.filter(t=>!t.gone);if(!live.some(t=>t.id===selected))selected=live[0]?.id;const cards=$('minase-cards');writeHTML(cards,live.map(t=>'<button class="terminal-train-card '+(t.id===selected?'selected':'')+'" data-train="'+t.id+'"><strong>'+t.id+' '+t.kind+'</strong><span>'+(t.from==='W'?'下り':'上り')+' ／ 所定'+t.p+'番線 ／ '+state(t)+'</span><small>'+t.note+' · 着 '+time(t.arr)+' / 発 '+time(t.dep)+'</small></button>').join('')||'<p class="muted">次の列車の接近を待っています。</p>');for(const b of cards.querySelectorAll('[data-train]'))b.onclick=()=>{selected=b.dataset.train;paint();};const t=live.find(t=>t.id===selected),d=desired(t);$('minase-guide').textContent=d?'① 白テコ '+Object.entries(d.req).map(([k,v])=>k+'='+ (v?'R':'N')).join(' ／ ')+' → ② 赤テコ '+(d.side==='E'&&d.dir==='in'?'上り場内（21で'+d.p+'番線選択）':d.id)+' を倒す。'+(s.check(d)||'進路構成できます。'):t?state(t):'列車を選ぶと、必要なテコ位置を案内します。';$('minase-locks').textContent=s.routes.map(r=>r.id+(r.cancel!==null?' 接近鎖錠 あと'+Math.ceil(r.cancel)+'秒':r.stage===-1?' 進路構成':' 進路鎖錠')).join(' ／ ')||'構成進路なし';
 for(const side of ['W','E'])$('block-'+side).textContent=(side==='W'?'西浜':'山岳')+'方：'+(s.lineBusy(side)?'在線・出発不可':'空き');writeHTML($('minase-table'),s.plan.map(p=>{const rec=s.records[p.id],m=rec.arrP!==null&&rec.arrP!==p.p;return'<tr class="'+(rec.dep!==null?'finishedrow':'')+'"><td>'+p.id+' '+p.kind+'</td><td>'+(p.from==='W'?'下り':'上り')+(p.from===p.to?' ↩':'')+'</td><td class="'+(m?'late':'')+'">'+p.p+(m?' → '+rec.arrP:'')+'番</td><td class="'+((rec.arr??s.time)>p.arr+.5?'late':'')+'">'+time(p.arr)+'</td><td class="'+((rec.dep??s.time)>p.dep+.5?'late':'')+'">'+time(p.dep)+'</td><td>'+actual(rec.arr,p.arr)+'</td><td>'+actual(rec.dep,p.dep)+'</td></tr>';}).join(''));$('minase-logs').textContent=s.logs.map(l=>time(l.time)+' '+l.text).join('\n');if(s.finished&&!shown){shown=true;paused=true;$('minase-modal').style.display='grid';$('minase-modal').innerHTML='<section class="modalbox"><div class="eyebrow">MINASE / SHIFT REPORT</div><h2>水瀬駅 勤務成績</h2><div class="terminal-grade">'+r.grade+' <strong>'+r.score+'点</strong></div><p>所定番線 '+r.correct+'/'+r.total+' ／ 定時発着 '+r.ontime+'/'+r.total+' ／ 発着完了 '+r.completed+'/'+r.total+'</p><p>延べ遅延 '+Math.round(r.delay)+'秒 ／ 最大遅延 '+Math.round(r.max)+'秒</p><p>番線30点・15秒以内の発着35点・完了35点。実績は盤面下のダイヤ表で確認できます。</p><div class="resultactions"><a class="station-select" href="index.html">駅選択</a><button id="minase-review">盤面と実績を確認</button><button id="minase-retry">次の勤務</button></div></section>';$('minase-review').onclick=()=>{$('minase-modal').style.display='none';};$('minase-retry').onclick=setup;}}
$('minase-new').onclick=setup;$('minase-pause').onclick=()=>{paused=!paused;paint();};$('minase-speed').onchange=e=>speed=+e.target.value;
function frame(now){const dt=Math.min(.5,Math.max(0,(now-last)/1000));last=now;gameClock.advance(station,!paused&&!document.hidden&&station.running,speed,now);for(const side of ['W','E'])sound.approach(side,station.trains.find(t=>!t.gone&&(t.loc===side+'I'||t.loc===side+'Q'))?.id||null);sound.pause(paused||document.hidden||!station.running||station.finished);sound.tick(dt);if(!paused&&!document.hidden&&(station.running||station.finished&&!shown)&&now-lastPaint>200){paint();lastPaint=now;}requestAnimationFrame(frame);}
$('minase-mute').onclick=()=>{audio.ready();sound.mute(!sound.muted);$('minase-mute').textContent=sound.muted?'音声 OFF':'音声 ON';};for(const side of ['W','E'])$('minase-stop-'+side).onclick=()=>{sound.silence(side);paint();};$('minase-volume').oninput=e=>{sound.level(+e.target.value/100);$('minase-volume-value').textContent=e.target.value+'%';paint();};document.addEventListener('visibilitychange',()=>{if(document.hidden)sound.pause(true);});build();paint();setup();requestAnimationFrame(frame);

